const dialogConfig = (state, methods) => ({
  opened: state.isOpen,
  icon: 'mdi-food',
  title: state.isAnEdition
    ? 'customPromotionsView.edit.title.combo'
    : 'customPromotionsView.create.title.combo',
  maxWidth: 760,
  cardStyles: { maxHeight: '800px', minHeight: '460px' },
  id: 'create-promotion-btn',
  persistent: true,
  buttonTextColor: {
    cancel: 'white',
    accept: 'white',
  },
  buttonColor: {
    cancel: 'accent',
    accept: 'primary',
  },
  onClickCancel: methods.closeDialog,
  onClickAccept: methods.save,
})

export default dialogConfig
