<template>
  <DialogCard :config="dialog">
    <template v-slot:titleRight>
      <v-spacer />
      <v-icon
        ref="favorite-heart"
        :color="inputs.favorite === 1 ? 'error' : 'accent'"
        @click="inputs.favorite = inputs.favorite === 1 ? 0 : 1"
      >
        {{ inputs.favorite === 1 ? 'mdi-heart' : 'mdi-heart-outline' }}
      </v-icon>
    </template>
    <v-form ref="comboForm">
      <AddComboProducts
        v-model="inputs"
        :validators="$v.inputs"
        :is-an-edition="!!promotionToEdit"
      />
      <AddComboPrice
        v-if="productAreSelected"
        v-model="inputs"
        :validators="$v.inputs"
        :is-an-edition="!!promotionToEdit"
      />
      <ActivationPromotion
        v-if="productAreSelected"
        v-model="inputs"
        :validators="$v.inputs"
      />
    </v-form>
    <template v-slot:leftFooter v-if="!!promotionToEdit">
      <DeleteCustomPromotion :promotion="promotionToEdit" />
    </template>
  </DialogCard>
</template>

<script>
import { maxValue, minValue, required } from 'vuelidate/lib/validators'

import { promotions } from '@/config/promotions'

import { formatNumberFromDb } from '@/tools/numbersFormat'

import DialogCard from '@/components/shared/DialogCard'
import dialogConfig from '@/components/CustomPromotionsView/CustomPromotionForm/ComboForm/config'
import AddComboProducts from '@/components/CustomPromotionsView/CustomPromotionForm/ComboForm/AddComboProducts'
import AddComboPrice from '@/components/CustomPromotionsView/CustomPromotionForm/ComboForm/AddComboPrice'
import ActivationPromotion from '@/components/CustomPromotionsView/CustomPromotionForm/ActivationPromotion'
import DeleteCustomPromotion from '@/components/CustomPromotionsView/DeleteCustomPromotion'

export default {
  name: 'ComboPromotionForm',
  components: {
    DeleteCustomPromotion,
    ActivationPromotion,
    AddComboPrice,
    AddComboProducts,
    DialogCard,
  },
  props: {
    dialogIsOpen: {
      type: Boolean,
      required: true,
    },
    promotionToEdit: {
      type: Object,
      default: null,
    },
  },
  data() {
    return {
      inputs: {
        promotions: {
          firstProduct: null,
          secondProduct: null,
          firstProductUnitPrice: 0,
          secondProductUnitPrice: 0,
          quantityFirstProduct: 1,
          quantitySecondProduct: 1,
          total: 0,
          totalWithoutPromo: 0,
        },
        active: 1,
        activatedWithDates: false,
        startDate: '',
        finishDate: '',
        favorite: 0,
      },
    }
  },
  computed: {
    dialog() {
      return dialogConfig(
        {
          isOpen: this.dialogIsOpen,
          isAnEdition: !!this.promotionToEdit,
        },
        {
          save: this.save,
          closeDialog: () => {
            this.$track({
              type: 'interaction',
              action: 'click',
              category: 'CustomPromotions',
              screen: 'ComboForm',
              name: 'Cancel',
            })
            this.$emit('close')
          },
        }
      )
    },
    productAreSelected() {
      return (
        !!this.inputs.promotions.firstProduct &&
        !!this.inputs.promotions.secondProduct
      )
    },
  },
  methods: {
    setInputsFromPromotionToEdit() {
      Object.keys(this.inputs).forEach(key => {
        if (key === 'activatedWithDates') {
          this.inputs.activatedWithDates = !!this.promotionToEdit.startDate
          return
        }
        if (!(key in this.promotionToEdit)) return
        if (key === 'promotions') {
          this.inputs.promotions = JSON.parse(
            JSON.stringify(this.promotionToEdit.promotions)
          )
          return
        }
        this.inputs[key] = this.promotionToEdit[key]
      })
      this.inputs.promotions.firstProductUnitPrice = formatNumberFromDb(
        this.promotionToEdit.promotions.firstProduct.price
      )
      this.inputs.promotions.secondProductUnitPrice = formatNumberFromDb(
        this.promotionToEdit.promotions.secondProduct.price
      )
      this.inputs.promotions.total = formatNumberFromDb(
        this.promotionToEdit.promotions.total
      )
      this.inputs.promotions.totalWithoutPromo =
        this.inputs.promotions.firstProductUnitPrice +
        this.inputs.promotions.secondProductUnitPrice
    },
    save() {
      this.$v.$touch()
      if (this.$v.$invalid) return
      this.$track({
        type: 'interaction',
        action: 'click',
        category: 'CustomPromotions',
        screen: 'ComboForm',
        name: 'Submit',
      })
      this.$emit('save', {
        ...this.inputs,
        type: promotions.SALE_ITEM_COMBO,
      })
    },
  },
  beforeMount() {
    if (this.promotionToEdit) {
      this.setInputsFromPromotionToEdit()
    }
  },
  validations() {
    return {
      inputs: {
        promotions: {
          firstProduct: { required },
          secondProduct: { required },
          firstProductUnitPrice: {
            required,
            minValue: (value, promotions) => {
              if (promotions.firstProduct && !!promotions.firstProduct.id) {
                return value >= 0.01
              }
              return value >= 0
            },
            maxValue: maxValue(999999),
          },
          secondProductUnitPrice: {
            required,
            minValue: (value, promotions) => {
              if (promotions.secondProduct && !!promotions.secondProduct.id) {
                return value >= 0.01
              }
              return value >= 0
            },
            maxValue: maxValue(999999),
          },
          total: {
            required,
            minValue: minValue(0.01),
            maxTotalCombo: (value, promotions) => {
              const { firstProduct, secondProduct } = promotions
              if (!firstProduct || !secondProduct) return true
              return value < promotions.totalWithoutPromo
            },
          },
        },
        startDate: {
          required: (value, promotions) => {
            if (promotions.activatedWithDates) return required(value)
            return true
          },
        },
      },
    }
  },
}
</script>
