<template>
  <MoreForLessForm
    v-if="showMoreForLessForm"
    :dialog-is-open="editCustomPromotionDialog.isOpen"
    :promotion-to-edit="promotion"
    @save="editPromotion"
    @close="closeDialog"
  />
  <ComboPromotionForm
    v-else-if="showComboForm"
    :dialog-is-open="editCustomPromotionDialog.isOpen"
    :promotion-to-edit="promotion"
    @save="editPromotion"
    @close="closeDialog"
  />
</template>

<script>
import { mapActions, mapState } from 'vuex'

import CUSTOM_PROMOTIONS_DB_API_EVENTS from '@/config/events/databaseAPI/customPromotionsEvents'
import { promotions } from '@/config/promotions'

import notificationsService from '@/services/renderer/notifications'
import rendererEventsService from '@/services/renderer/rendererEvents'

import customPromotionsViewActions from '@/store/customPromotionsView/actions.types'
import customPromotionsActions from '@/store/customPromotions/actions.types'

import MoreForLessForm from '@/components/CustomPromotionsView/CustomPromotionForm/MoreForLessForm'
import ComboPromotionForm from '@/components/CustomPromotionsView/CustomPromotionForm/ComboForm'
import tools from '@/components/CustomPromotionsView/EditCustomPromotion/editCustomPromotion.tools'

export default {
  name: 'EditCustomPromotion',
  components: { ComboPromotionForm, MoreForLessForm },
  data() {
    return {
      promotion: {},
      showNotification: true,
    }
  },
  computed: {
    ...mapState('customPromotionsView', ['editCustomPromotionDialog']),
    ...mapState('usersView', {
      userId: state => state.selectedUser.id,
    }),
    showMoreForLessForm() {
      return (
        this.editCustomPromotionDialog.isOpen &&
        Object.values(this.promotion).length &&
        this.promotion.type === promotions.SALE_ITEM_MORE_FOR_LESS
      )
    },
    showComboForm() {
      return (
        this.editCustomPromotionDialog.isOpen &&
        Object.values(this.promotion).length &&
        this.promotion.type === promotions.SALE_ITEM_COMBO
      )
    },
  },
  methods: {
    ...mapActions('customPromotionsView', [
      customPromotionsViewActions.setEditCustomPromotionDialogStatus,
    ]),
    ...mapActions('customPromotions', [
      customPromotionsActions.saveCustomPromotion,
    ]),
    openDialog(promotion) {
      this.$root.$emit('clearFilters')
      if (!promotion || !Object.values(promotion).length) return
      this.promotion = promotion
      this[customPromotionsViewActions.setEditCustomPromotionDialogStatus](true)
    },
    toggleFavorite(promotion) {
      this.promotion = promotion
      this.editPromotion(
        {
          ...promotion,
          favorite: promotion.favorite === 0 ? 1 : 0,
        },
        false
      )
    },
    changeActivePromotion(promotion) {
      this.promotion = promotion
      this.editPromotion(
        {
          ...promotion,
          active: promotion.active === 0 ? 1 : 0,
          startDate: '',
          finishDate: '',
        },
        false
      )
    },
    editPromotion(promotion, fromForm = true) {
      this.$loading.show('editCustomPromotion')
      rendererEventsService.send(CUSTOM_PROMOTIONS_DB_API_EVENTS.channel, {
        event: CUSTOM_PROMOTIONS_DB_API_EVENTS.events.edit.name,
        data: {
          promotion: tools.getPromotionToDbFactory(
            {
              promotionToEdit: this.promotion,
              promotionEdited: promotion,
            },
            fromForm
          ),
          uneditedPromotion: this.promotion,
          userId: this.userId,
        },
      })
    },
    closeDialog() {
      this[customPromotionsViewActions.setEditCustomPromotionDialogStatus](
        false
      )
      this.promotion = {}
    },
    promotionsListener(event, payload) {
      const replies = {
        [CUSTOM_PROMOTIONS_DB_API_EVENTS.events.edit.replies.success]: () => {
          this.$track({
            type: 'system',
            action: 'save_promotion',
            category: 'CustomPromotions',
            screen: 'EditCustomPromotion',
            name: 'Close dialog',
          })
          if (this.showNotification) {
            notificationsService.showSuccess(
              'customPromotionsView.edit.success',
              this.$vuetify.lang
            )
          }
          this[customPromotionsActions.saveCustomPromotion](
            payload.data.promotion
          )
          this.closeDialog()
        },
        [CUSTOM_PROMOTIONS_DB_API_EVENTS.events.edit.replies.error]: () => {
          this.$track({
            type: 'system',
            action: 'save_promotion',
            category: 'CustomPromotions',
            screen: 'EditCustomPromotion',
            name: 'Error editing custom promotion',
          })
          if (this.showNotification) {
            notificationsService.showError(
              'customPromotionsView.edit.error',
              this.$vuetify.lang
            )
          }
        },
      }
      if (payload.event in replies) {
        replies[payload.event]()
        this.$loading.hide()
        this.showNotification = true
      }
    },
  },
  beforeMount() {
    this.$root.$on('openEditPromotion', this.openDialog)
    this.$root.$on('togglePromotionFavorite', this.toggleFavorite)
    this.$root.$on('changeActivePromotion', this.changeActivePromotion)
    rendererEventsService.subscribe(
      CUSTOM_PROMOTIONS_DB_API_EVENTS.replyChannel,
      this.promotionsListener
    )
  },
  beforeDestroy() {
    this.$root.$off('openEditPromotion', this.openDialog)
    this.$root.$off('togglePromotionFavorite', this.toggleFavorite)
    this.$root.$off('changeActivePromotion', this.changeActivePromotion)
    rendererEventsService.removeListener(
      CUSTOM_PROMOTIONS_DB_API_EVENTS.replyChannel,
      this.promotionsListener
    )
  },
}
</script>
