const config = (state, methods) => ({
  state,
  methods,
  dialog: {
    opened: state.isOpen,
    height: 225,
    maxWidth: 500,
    icon: 'mdi-delete',
    title: 'customPromotionsView.deleteDisabled.title',
    messages: ['customPromotionsView.deleteDisabled.text'],
    persistent: true,
    buttonTextColor: {
      cancel: 'white',
      accept: 'white',
    },
    buttonColor: {
      cancel: 'accent',
      accept: 'primary',
    },
    onClickCancel: () => {
      methods.track({
        type: 'interaction',
        action: 'click',
        category: 'CustomPromotions',
        screen: 'DeleteDisabledCustomPromotions',
        name: 'Cancel confirm',
      })
      methods.closeDialog()
    },
    onClickAccept: methods.acceptDeletion,
  },
})

export default config
