<template>
  <v-row class="promotions-row">
    <v-col cols="12" class="py-0">
      <p class="text-subtitle-1 font-weight-bold mb-0">
        {{ getTranslatedText('customPromotionsView.form.promotions') }}
      </p>
    </v-col>
    <v-col cols="12" :class="{ 'pb-0': value.promotions.length < 4 }">
      <ScrollContainer
        :height="heightScroll"
        :max-height="this.value.product.factor > 0 ? '210px' : '290px'"
        :scroll-active-style="{ 'margin-right': '-20px' }"
        ref="scrollPromotionsRows"
      >
        <v-row
          v-for="(promotion, index) in value.promotions"
          :key="`promotion-form-${index}`"
          class="promotion-row"
          align="center"
        >
          <v-col cols="4" class="pb-0">
            <v-text-field
              v-model.number="promotion.quantity"
              type="number"
              class="custom-text-field"
              :label="
                getTranslatedText(
                  `customPromotionsView.form.${
                    value.product.factor <= 0 ? 'units' : 'packages'
                  }`
                )
              "
              filled
              rounded
              :error-messages="errorMessages('quantity', index)"
              @blur="onBlur(index, 'quantity')"
              @input="setPromotionUnitPrice(index)"
            />
          </v-col>
          <v-col cols="4" class="pb-0">
            <MoneyTextField
              v-model.number="promotion.total"
              :config="{
                fieldName: 'total',
                color: 'primary',
                filled: true,
                rounded: true,
                label: getTranslatedText(
                  'customPromotionsView.form.totalPromotion'
                ),
                class: 'custom-text-field',
                backgroundColor: 'cardBackgroundSecondary',
                errorMessage: () => errorMessages('total', index),
                readonly: false,
              }"
              :options="moneyInputsConfig"
              @blur="onBlur(index, 'total')"
              @input="setPromotionUnitPrice(index)"
            />
          </v-col>
          <v-col :cols="index === 0 ? 4 : 3" class="pb-0">
            <MoneyTextField
              v-model.number="promotion.promotionUnitPrice"
              :config="{
                fieldName: 'total',
                color: 'primary',
                filled: true,
                rounded: true,
                label: getTranslatedText(
                  'customPromotionsView.form.unitPricePromotion'
                ),
                backgroundColor: 'cardBackgroundSecondary',
                errorMessage: () => {},
                readonly: true,
              }"
              :options="moneyInputsConfig"
            />
          </v-col>
          <v-col v-if="index > 0" cols="1" class="pb-0 pr-1">
            <v-tooltip bottom>
              <template v-slot:activator="{ on }">
                <v-btn
                  icon
                  v-on="on"
                  class="mb-8"
                  color="error"
                  @click="deletePromotion(index)"
                >
                  <v-icon>mdi-delete</v-icon>
                </v-btn>
              </template>
              <span>
                {{
                  getTranslatedText('customPromotionsView.form.deletePromotion')
                }}
              </span>
            </v-tooltip>
          </v-col>
        </v-row>
      </ScrollContainer>
    </v-col>
    <v-col cols="12" class="pt-0">
      <v-btn text small color="primary" @click="addPromotionRow">
        <v-icon>mdi-plus</v-icon>
        {{ getTranslatedText('customPromotionsView.form.addPromotion') }}
      </v-btn>
    </v-col>
  </v-row>
</template>

<script>
import { moneyTextFieldCountryConfig } from '@/tools/numbersFormat'
import { validate } from '@/tools/validations'
import { getTranslatedText } from '@/tools/data'

import MoneyTextField from '@/components/shared/MoneyTextField'
import ScrollContainer from '@/components/shared/ScrollContainer'

export default {
  name: 'AddPromotionsList',
  components: { ScrollContainer, MoneyTextField },
  props: {
    value: {
      Object: Array,
      default: () => [],
    },
    validators: {
      type: Object,
      required: true,
    },
    isAnEdition: {
      type: Boolean,
      default: false,
    },
  },
  computed: {
    heightScroll() {
      const isOpenProduct = this.value.product.factor > 0
      const maxLength = !isOpenProduct ? 4 : 3
      if (this.value.promotions.length < maxLength) {
        return `${106 * this.value.promotions.length}px`
      }
      return !isOpenProduct ? '290px' : '210px'
    },
    moneyInputsConfig() {
      return moneyTextFieldCountryConfig() || { precision: 2 }
    },
  },
  methods: {
    getTranslatedText,
    onBlur(index, input) {
      this.validators.promotions.$each.$iter[index][input].$touch()
    },
    errorMessages(input, index) {
      return validate(
        this.validators.promotions.$each.$iter[index],
        input,
        {
          fn: this.getTranslatedText,
        },
        [
          {
            name: 'minQuantity',
            error: 'customPromotionsView.form.error.minQuantity',
          },
          {
            name: 'quantityExist',
            error: 'customPromotionsView.form.error.quantityExist',
          },
          {
            name: 'maxUnitPrice',
            error: 'customPromotionsView.form.error.maxUnitPrice',
          },
        ]
      )
    },
    setPromotionUnitPrice(index) {
      if (
        this.value.promotions[index].quantity <= 0 ||
        this.value.promotions[index].total <= 0
      ) {
        this.value.promotions[index].promotionUnitPrice = 0
      }
      this.value.promotions[index].promotionUnitPrice =
        this.value.promotions[index].total /
        this.value.promotions[index].quantity
    },
    addPromotionRow() {
      this.value.promotions.push({
        quantity:
          this.value.promotions[this.value.promotions.length - 1].quantity + 1,
        total: 0,
        promotionUnitPrice: 0,
      })
      setTimeout(() => {
        this.scrollBottom()
      }, 300)
    },
    deletePromotion(index) {
      this.value.promotions.splice(index, 1)
    },
    scrollBottom() {
      this.$refs.scrollPromotionsRows.scrollToBottom()
    },
  },
}
</script>
