<template>
  <ToolBar :config="filtersConfig" />
</template>

<script>
import { mapActions, mapState } from 'vuex'

import { getTranslatedText } from '@/tools/data'

import customPromotionsViewActions from '@/store/customPromotionsView/actions.types'

import ToolBar from '@/components/shared/ToolBar'
import filtersConfig from '@/components/CustomPromotionsView/CustomPromotionsToolbar/Filters/config'

export default {
  name: 'CustomPromotionsFilters',
  components: { ToolBar },
  computed: {
    ...mapState('customPromotionsView', ['filters']),
    filtersConfig() {
      return filtersConfig(
        { filters: this.filters },
        {
          addPromotion: this.addPromotion,
          updateSearch: this.updateSearch,
          filterWasSelected: this.filterWasSelected,
          clearFilters: this.clearFilters,
          getTranslatedText: this.getTranslatedText,
        }
      )
    },
  },
  methods: {
    getTranslatedText,
    ...mapActions('customPromotionsView', [
      customPromotionsViewActions.updateFilters,
    ]),
    addPromotion(item) {
      this.$track({
        type: 'interaction',
        action: 'click',
        category: 'CustomPromotions',
        screen: 'Toolbar',
        name: `Create ${item.track} promotion`,
      })
      this.$root.$emit('openCreatePromotion', item.id)
    },
    updateSearch(value) {
      if (value && value.trim().length < 3) return
      this[customPromotionsViewActions.updateFilters]({ search: value })
    },
    filterWasSelected(group) {
      this[customPromotionsViewActions.updateFilters]({ group })
    },
    clearFilters() {
      this.$root.$emit('reset')
      this[customPromotionsViewActions.updateFilters]({
        search: null,
        group: 'all',
      })
    },
    searchByBarcode(barcode) {
      this.$root.$emit('default-value', {
        input: 'search-control',
        value: barcode,
      })
      this[customPromotionsViewActions.updateFilters]({
        search: barcode,
        group: 'all',
      })
    },
    initBarcode() {
      this.$barcodeScanner.init(this.searchByBarcode)
    },
  },
  created() {
    this.$barcodeScanner.init(this.searchByBarcode)
    this.$root.$on('enable-scanner', this.initBarcode)
    this.$root.$on('enable-scanner-from-form', this.initBarcode)
    this.$root.$on('clearFilters', this.clearFilters)
  },
  mounted() {
    if (this.$route.query && this.$route.query.search) {
      this.searchByBarcode(this.$route.query.search)
      this.$router.replace({ query: {} })
    }
  },
  beforeDestroy() {
    this.$barcodeScanner.destroy()
    this.$root.$emit('enable-scanner')
    this.$root.$off('clearFilters', this.clearFilters)
  },
}
</script>
