<template>
  <v-row>
    <v-col cols="12" class="py-0">
      <p class="text-subtitle-1 font-weight-bold mb-0">
        {{ getTranslatedText('customPromotionsView.form.comboPrice') }}
      </p>
    </v-col>
    <v-col cols="8">
      <MoneyTextField
        v-model.number="value.promotions.total"
        :config="{
          fieldName: 'total',
          color: 'primary',
          filled: true,
          rounded: true,
          label: getTranslatedText('customPromotionsView.form.totalCombo'),
          class: 'custom-text-field',
          backgroundColor: 'cardBackgroundSecondary',
          errorMessage: errorMessages,
          readonly: false,
        }"
        :options="moneyInputsConfig"
        @blur="onBlur('total')"
      />
    </v-col>
    <v-col cols="4">
      <MoneyTextField
        v-model.number="value.promotions.totalWithoutPromo"
        :config="{
          fieldName: 'total',
          color: 'primary',
          filled: true,
          rounded: true,
          label: getTranslatedText(
            'customPromotionsView.form.totalWithoutPromotion'
          ),
          backgroundColor: 'cardBackgroundSecondary',
          errorMessage: () => {},
          readonly: true,
        }"
        :options="moneyInputsConfig"
      />
    </v-col>
  </v-row>
</template>

<script>
import { getTranslatedText } from '@/tools/data'
import { validate } from '@/tools/validations'
import { moneyTextFieldCountryConfig } from '@/tools/numbersFormat'

import MoneyTextField from '@/components/shared/MoneyTextField'

export default {
  name: 'AddComboPrice',
  components: { MoneyTextField },
  props: {
    value: {
      type: Object,
      default: null,
    },
    validators: {
      type: Object,
      required: true,
    },
    isAnEdition: {
      type: Boolean,
      default: false,
    },
  },
  computed: {
    moneyInputsConfig() {
      return moneyTextFieldCountryConfig() || { precision: 2 }
    },
  },
  methods: {
    getTranslatedText,
    errorMessages(input) {
      return validate(
        this.validators.promotions,
        input,
        {
          fn: this.getTranslatedText,
        },
        [
          {
            name: 'maxTotalCombo',
            error: 'customPromotionsView.form.error.maxTotalCombo',
          },
        ]
      )
    },
    onBlur(input) {
      this.validators.promotions[input].$touch()
    },
  },
  destroyed() {
    this.value.promotions.total = 0
    this.validators.promotions.total.$reset()
  },
}
</script>
