<template>
  <DialogCard :config="dialog">
    <template v-slot:titleRight>
      <v-spacer />
      <v-icon
        ref="favorite-heart"
        :color="inputs.favorite === 1 ? 'error' : 'accent'"
        @click="inputs.favorite = inputs.favorite === 1 ? 0 : 1"
      >
        {{ inputs.favorite === 1 ? 'mdi-heart' : 'mdi-heart-outline' }}
      </v-icon>
    </template>
    <v-form ref="moreForLessForm">
      <AddProductToPromote
        v-model="inputs"
        :validators="$v.inputs"
        :isAnEdition="!!promotionToEdit"
      />
      <AddPromotionsList
        v-if="inputs.product && inputs.product.id"
        v-model="inputs"
        :validators="$v.inputs"
        :isAnEdition="!!promotionToEdit"
      />
      <ActivationPromotion
        v-if="inputs.product && inputs.product.id"
        v-model="inputs"
        :validators="$v.inputs"
      />
    </v-form>
    <template v-slot:leftFooter v-if="!!promotionToEdit">
      <DeleteCustomPromotion :promotion="promotionToEdit" />
    </template>
  </DialogCard>
</template>

<script>
import { integer, maxValue, minValue, required } from 'vuelidate/lib/validators'

import { promotions } from '@/config/promotions'

import {
  formatNumberFromDb,
  moneyTextFieldCountryConfig,
} from '@/tools/numbersFormat'
import { getTranslatedText } from '@/tools/data'

import AddProductToPromote from '@/components/CustomPromotionsView/CustomPromotionForm/MoreForLessForm/AddProductToPromote'
import AddPromotionsList from '@/components/CustomPromotionsView/CustomPromotionForm/MoreForLessForm/AddPromotionsList'
import ActivationPromotion from '@/components/CustomPromotionsView/CustomPromotionForm/ActivationPromotion'
import DialogCard from '@/components/shared/DialogCard'
import dialogConfig from '@/components/CustomPromotionsView/CustomPromotionForm/MoreForLessForm/config'
import DeleteCustomPromotion from '@/components/CustomPromotionsView/DeleteCustomPromotion'

export default {
  name: 'MoreForLessForm',
  components: {
    DeleteCustomPromotion,
    DialogCard,
    ActivationPromotion,
    AddProductToPromote,
    AddPromotionsList,
  },
  props: {
    dialogIsOpen: {
      type: Boolean,
      required: true,
    },
    promotionToEdit: {
      type: Object,
      default: null,
    },
  },
  data() {
    return {
      inputs: {
        product: {},
        unitPrice: 0,
        promotions: [{ quantity: 2, total: 0, promotionUnitPrice: 0 }],
        active: 1,
        activatedWithDates: false,
        startDate: '',
        finishDate: '',
        favorite: 0,
      },
    }
  },
  computed: {
    dialog() {
      return dialogConfig(
        {
          isOpen: this.dialogIsOpen,
          isAnEdition: !!this.promotionToEdit,
        },
        {
          save: this.save,
          closeDialog: () => {
            this.$track({
              type: 'interaction',
              action: 'click',
              category: 'CustomPromotions',
              screen: 'MoreForLessForm',
              name: 'Cancel',
            })
            this.$emit('close')
          },
        }
      )
    },
  },
  methods: {
    formatNumberFromDb,
    moneyTextFieldCountryConfig,
    getTranslatedText,
    quantityNotAlreadyExist(quantity) {
      return (
        this.inputs.promotions.filter(promo => promo.quantity === quantity)
          .length <= 1
      )
    },
    promotionalUnitPriceIsLessThanUnitPrice(price) {
      return price < this.inputs.unitPrice
    },
    save() {
      this.$v.$touch()
      if (this.$v.$invalid) return
      this.$track({
        type: 'interaction',
        action: 'click',
        category: 'CustomPromotions',
        screen: 'MoreForLessForm',
        name: 'Submit',
      })
      this.$emit('save', {
        ...this.inputs,
        type: promotions.SALE_ITEM_MORE_FOR_LESS,
      })
    },
    setInputsFromPromotionToEdit() {
      Object.keys(this.inputs).forEach(key => {
        if (key === 'unitPrice') {
          this.inputs.unitPrice = formatNumberFromDb(
            Number(this.promotionToEdit.product.price)
          )
          return
        }
        if (key === 'promotions') {
          this.inputs.promotions = this.promotionToEdit[key].map(promo => ({
            quantity: promo.quantity,
            total: formatNumberFromDb(promo.total),
            promotionUnitPrice:
              formatNumberFromDb(promo.total) / promo.quantity,
            id: promo.id,
          }))
          return
        }
        if (key === 'activatedWithDates') {
          this.inputs.activatedWithDates = !!this.promotionToEdit.startDate
          return
        }
        this.inputs[key] = this.promotionToEdit[key]
      })
    },
  },
  beforeMount() {
    if (this.promotionToEdit) {
      this.setInputsFromPromotionToEdit()
    }
  },
  validations() {
    return {
      inputs: {
        product: { required },
        unitPrice: {
          required,
          minValue: (value, promotion) => {
            if (promotion.product && !!promotion.product.id) {
              return value >= 0.01
            }
            return value >= 0
          },
          maxValue: maxValue(999999),
        },
        startDate: {
          required: (value, args) => {
            if (args.activatedWithDates) return required(value)
            return true
          },
        },
        promotions: {
          $each: {
            quantity: {
              required,
              integer,
              minQuantity: minValue(2),
              quantityExist: value => this.quantityNotAlreadyExist(value),
            },
            total: {
              required,
              minValue: minValue(0.01),
              maxUnitPrice: (value, promotion) =>
                this.promotionalUnitPriceIsLessThanUnitPrice(
                  promotion.promotionUnitPrice
                ),
            },
          },
        },
      },
    }
  },
}
</script>
