import { promotions } from '@/config/promotions'

import { formatNumberToDb } from '@/tools/numbersFormat'

const getPromotionToDbFactory = (promotion, fromForm) => {
  if (promotion.promotionToEdit.type === promotions.SALE_ITEM_MORE_FOR_LESS) {
    return getMoreForLessPromotionToDB(promotion, fromForm)
  }
  return getComboPromotionToDB(promotion, fromForm)
}

const getMoreForLessPromotionToDB = (promotion, fromForm) => {
  const { promotionToEdit, promotionEdited } = promotion
  return {
    ...promotionToEdit,
    ...promotionEdited,
    promotions: promotionEdited.promotions.map(promo => ({
      ...promo,
      total: fromForm ? formatNumberToDb(promo.total) : promo.total,
      promotionUnitPrice: fromForm
        ? formatNumberToDb(promo.promotionUnitPrice)
        : promo.promotionUnitPrice,
    })),
    product: fromForm ? promotionToEdit.product : promotionEdited.product,
  }
}

const getComboPromotionToDB = (promotion, fromForm) => {
  const { promotionToEdit, promotionEdited } = promotion
  return {
    ...promotionToEdit,
    ...promotionEdited,
    promotions: {
      ...promotionToEdit.promotions,
      ...promotionEdited.promotions,
      firstProductUnitPrice: fromForm
        ? formatNumberToDb(promotionEdited.promotions.firstProductUnitPrice)
        : promotionEdited.promotions.firstProductUnitPrice,
      secondProductUnitPrice: fromForm
        ? formatNumberToDb(promotionEdited.promotions.secondProductUnitPrice)
        : promotionEdited.promotions.secondProductUnitPrice,
      total: fromForm
        ? formatNumberToDb(promotionEdited.promotions.total)
        : promotionEdited.promotions.total,
    },
  }
}

export default {
  getPromotionToDbFactory,
}
