import { promotions } from '@/config/promotions'

import { formatNumberToDb } from '@/tools/numbersFormat'

const getPromotionToDBFactory = promotion => {
  if (promotion.type === promotions.SALE_ITEM_MORE_FOR_LESS) {
    return getMoreForLessPromotionToDB(promotion)
  }
  return getComboPromotionToDB(promotion)
}

const getMoreForLessPromotionToDB = promotion => {
  return {
    ...promotion,
    unitPrice: formatNumberToDb(promotion.unitPrice),
    promotions: promotion.promotions.map(promo => ({
      ...promo,
      total: formatNumberToDb(promo.total),
      promotionUnitPrice: formatNumberToDb(promo.promotionUnitPrice),
    })),
  }
}

const getComboPromotionToDB = promotion => {
  return {
    ...promotion,
    promotions: {
      ...promotion.promotions,
      firstProductId: promotion.promotions.firstProduct.id,
      secondProductId: promotion.promotions.secondProduct.id,
      firstProductUnitPrice: formatNumberToDb(
        promotion.promotions.firstProductUnitPrice
      ),
      secondProductUnitPrice: formatNumberToDb(
        promotion.promotions.secondProductUnitPrice
      ),
      quantityFirstProduct: 1,
      quantitySecondProduct: 1,
      total: formatNumberToDb(promotion.promotions.total),
    },
  }
}

export default {
  getPromotionToDBFactory,
}
