<template>
  <v-row align="center">
    <v-col cols="12" class="py-0 d-flex align-center">
      <p class="text-subtitle-1 font-weight-bold mb-0">
        {{ getTranslatedText('customPromotionsView.form.activation') }}
      </p>
      <v-checkbox
        v-model="value.activatedWithDates"
        :label="
          getTranslatedText('customPromotionsView.form.activationWithDates')
        "
        hide-details
        dense
        class="mt-0 ml-4 mb-1 activate-with-date"
        @change="activationWithDatesWasChanged"
      />
    </v-col>
    <v-col cols="4">
      <v-switch
        v-model="value.active"
        :false-value="0"
        :true-value="1"
        :label="labelSwitch"
        :readonly="value.activatedWithDates"
        inset
        class="pl-2 mb-4"
      />
    </v-col>
    <v-col cols="4" v-if="value.activatedWithDates">
      <DatePicker
        v-model="value.startDate"
        label="customPromotionsView.form.startDate"
        intl
        :min-date="getNow(false)"
        :max-date="value.finishDate"
        :error-messages="errorMessages('startDate')"
        @input="startDateWasUpdated"
      />
    </v-col>
    <v-col cols="4" v-if="value.activatedWithDates">
      <DatePicker
        v-model="value.finishDate"
        label="customPromotionsView.form.finishDate"
        intl
        :min-date="value.startDate"
        :readonly="!value.startDate"
        @input="finishDateWasUpdated"
      />
    </v-col>
  </v-row>
</template>

<script>
import { getTranslatedText } from '@/tools/data'
import {
  dayIsTodayOrAfter,
  dayIsTodayOrBefore,
  getDateWithFormat,
  getNow,
} from '@/tools/dates'
import { validate } from '@/tools/validations'

import DatePicker from '@/components/shared/DatePicker'

export default {
  name: 'ActivationPromotion',
  components: { DatePicker },
  props: {
    value: {
      type: Object,
      default: null,
    },
    validators: {
      type: Object,
      required: true,
    },
  },
  computed: {
    labelSwitch() {
      return this.getTranslatedText(
        `customPromotionsView.form.${
          this.value.active === 1 ? 'active' : 'disabled'
        }`
      )
    },
  },
  methods: {
    getNow,
    getTranslatedText,
    errorMessages(input) {
      return validate(this.validators, input, { fn: this.getTranslatedText })
    },
    activationWithDatesWasChanged(value) {
      if (value) {
        this.value.startDate = getDateWithFormat(getNow(), 'YYYY-MM-DD')
        this.value.active = 1
        return
      }
      this.value.startDate = ''
      this.value.finishDate = ''
      this.value.active = 1
    },
    startDateWasUpdated(value) {
      this.validators.startDate.$touch()
      if (!value) {
        this.value.finishDate = ''
      }
      this.updateActiveByDate()
    },
    async finishDateWasUpdated() {
      this.updateActiveByDate()
    },
    updateActiveByDate() {
      if (this.isTodayBetweenStartAndFinishDate()) {
        this.value.active = 1
        return
      }
      this.value.active = 0
    },
    isTodayBetweenStartAndFinishDate() {
      if (!this.value.finishDate) {
        return dayIsTodayOrBefore(this.value.startDate)
      }
      return (
        dayIsTodayOrBefore(this.value.startDate) &&
        dayIsTodayOrAfter(this.value.finishDate)
      )
    },
  },
}
</script>
<style lang="scss" scoped>
.activate-with-date {
  :deep(label) {
    font-size: 14px;
  }
}
</style>
