<template>
  <MoreForLessForm
    v-if="showMoreForLessForm"
    :dialogIsOpen="createCustomPromotionDialog.isOpen"
    @save="createPromotion"
    @close="closeDialog"
  />
  <ComboPromotionForm
    v-else-if="showComboForm"
    :dialog-is-open="createCustomPromotionDialog.isOpen"
    @save="createPromotion"
    @close="closeDialog"
  />
</template>

<script>
import { mapActions, mapState } from 'vuex'

import { promotions } from '@/config/promotions'
import CUSTOM_PROMOTIONS_DB_API_EVENTS from '@/config/events/databaseAPI/customPromotionsEvents'

import rendererEventsService from '@/services/renderer/rendererEvents'
import notificationsService from '@/services/renderer/notifications'

import customPromotionsViewActions from '@/store/customPromotionsView/actions.types'
import customPromotionsActions from '@/store/customPromotions/actions.types'
import productsActions from '@/store/products/actions.types'

import MoreForLessForm from '@/components/CustomPromotionsView/CustomPromotionForm/MoreForLessForm'
import ComboPromotionForm from '@/components/CustomPromotionsView/CustomPromotionForm/ComboForm'
import tools from '@/components/CustomPromotionsView/CreateCustomPromotion/createCustomPromotion.tools'

export default {
  name: 'CreateCustomPromotion',
  components: { ComboPromotionForm, MoreForLessForm },
  computed: {
    ...mapState('customPromotionsView', ['createCustomPromotionDialog']),
    ...mapState('usersView', {
      userId: state => state.selectedUser.id,
    }),
    showMoreForLessForm() {
      return (
        this.createCustomPromotionDialog.isOpen &&
        this.createCustomPromotionDialog.promotionType ===
          promotions.SALE_ITEM_MORE_FOR_LESS
      )
    },
    showComboForm() {
      return (
        this.createCustomPromotionDialog.isOpen &&
        this.createCustomPromotionDialog.promotionType ===
          promotions.SALE_ITEM_COMBO
      )
    },
  },
  methods: {
    ...mapActions('customPromotions', [
      customPromotionsActions.saveCustomPromotion,
    ]),
    ...mapActions('customPromotionsView', [
      customPromotionsViewActions.setCreateCustomPromotionDialogStatus,
    ]),
    ...mapActions('products', [productsActions.updateProductByProperties]),
    openDialog(promotionType) {
      this.$root.$emit('clearFilters')
      this[customPromotionsViewActions.setCreateCustomPromotionDialogStatus]({
        isOpen: true,
        type: promotionType,
      })
    },
    createPromotion(data) {
      this.$loading.show('createCustomPromotion')
      rendererEventsService.send(CUSTOM_PROMOTIONS_DB_API_EVENTS.channel, {
        event: CUSTOM_PROMOTIONS_DB_API_EVENTS.events.create.name,
        data: {
          promotion: tools.getPromotionToDBFactory(data),
          userId: this.userId,
        },
      })
    },
    closeDialog() {
      this[customPromotionsViewActions.setCreateCustomPromotionDialogStatus]({
        isOpen: false,
        type: null,
      })
    },
    toggleCreateForEdit(promotionToEdit) {
      this.$track({
        type: 'system',
        action: 'promotion_exist',
        category: 'CustomPromotions',
        screen: 'CreateCustomPromotion',
        name: 'Show edit custom promotion',
      })
      this.closeDialog()
      this.$root.$emit('openEditPromotion', promotionToEdit)
    },
    promotionsListener(event, payload) {
      const replies = {
        [CUSTOM_PROMOTIONS_DB_API_EVENTS.events.create.replies.success]: () => {
          this.$track({
            type: 'system',
            action: 'save_promotion',
            category: 'CustomPromotions',
            screen: 'CreateCustomPromotion',
            name: 'Close dialog',
          })
          notificationsService.showSuccess(
            'customPromotionsView.create.success',
            this.$vuetify.lang
          )
          payload.data.promotion.products.forEach(product => {
            this[productsActions.updateProductByProperties]({
              _id: product._id,
              prod_price: product.prod_price,
              is_price_changed: 1,
            })
            this.$root.$emit('productWasEdited', product._id)
          })
          this[customPromotionsActions.saveCustomPromotion](
            payload.data.promotion
          )
          this.closeDialog()
        },
        [CUSTOM_PROMOTIONS_DB_API_EVENTS.events.create.replies.error]: () => {
          this.$track({
            type: 'system',
            action: 'error',
            category: 'CustomPromotions',
            screen: 'CreateCustomPromotion',
            name: 'Error creating custom promotion',
          })
          notificationsService.showError(
            'customPromotionsView.create.error',
            this.$vuetify.lang
          )
        },
      }
      if (payload.event in replies) {
        replies[payload.event]()
        this.$loading.hide()
      }
    },
  },
  beforeMount() {
    this.$root.$on('openCreatePromotion', this.openDialog)
    this.$root.$on('toggleCreateForEdit', this.toggleCreateForEdit)
    rendererEventsService.subscribe(
      CUSTOM_PROMOTIONS_DB_API_EVENTS.replyChannel,
      this.promotionsListener
    )
  },
  beforeDestroy() {
    this.$root.$off('openCreatePromotion', this.openDialog)
    this.$root.$off('toggleCreateForEdit', this.toggleCreateForEdit)
    rendererEventsService.removeListener(
      CUSTOM_PROMOTIONS_DB_API_EVENTS.replyChannel,
      this.promotionsListener
    )
  },
}
</script>
