<template>
  <v-row>
    <v-col cols="12" class="py-0">
      <p class="text-subtitle-1 font-weight-bold mb-0">
        {{ getTranslatedText('customPromotionsView.form.comboProducts') }}
      </p>
    </v-col>
    <v-col cols="12" v-if="someProductAsOpenProduct">
      <v-alert
        dense
        color="secondary"
        text
        icon="mdi-alert-circle-outline"
        class="mb-0"
      >
        <span
          v-html="
            getTranslatedText('customPromotionsView.form.alertOpenProduct')
          "
        />
      </v-alert>
    </v-col>
    <v-row v-for="(key, index) in productsSelectorKeys" :key="key" class="ma-0">
      <v-col cols="8" :class="{ 'pb-0': index === 0 }">
        <ProductAutoComplete
          v-model="value.promotions[key]"
          :items="products[key]"
          :label="getTranslatedText('customPromotionsView.form.scan')"
          return-object
          :clearable="!isAnEdition"
          :menu-props="{ 'max-width': '460px' }"
          :error-message="errorMessages(key)"
          :on-blur="() => onBlur(key)"
          :readonly="isAnEdition"
          :loading="isAnEdition ? false : loading"
          item-text="text"
          :className="!isAnEdition ? 'custom-text-field' : ''"
          :custom-filter="customFilter"
          @searchInputUpdated="searchInMlp"
          @input="value => productWasSelected(key, value)"
          @focus="selectorWasFocused(key)"
        >
          <template v-slot:extraInfo="{ item }">
            <span
              v-if="productInCombo(key, item)"
              class="ml-4 d-flex align-center"
            >
              <v-icon class="mr-1">mdi-sale</v-icon>
              {{ getTranslatedText('customPromotionsView.form.onPromotion') }}
            </span>
          </template>
        </ProductAutoComplete>
      </v-col>
      <v-col cols="4" :class="{ 'pb-0': index === 0 }">
        <MoneyTextField
          v-model.number="value.promotions[`${key}UnitPrice`]"
          :config="{
            fieldName: `${key}UnitPrice`,
            color: 'primary',
            filled: true,
            rounded: true,
            class: !isAnEdition ? 'custom-text-field' : '',
            label: getTranslatedText('customPromotionsView.form.unitPrice'),
            backgroundColor: 'cardBackgroundSecondary',
            errorMessage: errorMessages,
            readonly: value.promotions[key]
              ? !value.promotions[key].id || isAnEdition
              : false,
          }"
          :options="moneyInputsConfig"
          @blur="validators.promotions[`${key}UnitPrice`].$touch()"
          @input="setTotalWithoutPromo"
        />
      </v-col>
    </v-row>
  </v-row>
</template>

<script>
import { mapActions, mapGetters, mapState } from 'vuex'

import MLP_DB_API_EVENTS from '@/config/events/databaseAPI/mlpEvents'
import ADD_PRODUCT_EVENTS from '@/config/events/addProduct'
import { promotions } from '@/config/promotions'

import { getTranslatedText } from '@/tools/data'

import { validate } from '@/tools/validations'

import {
  formatNumberFromDb,
  moneyTextFieldCountryConfig,
} from '@/tools/numbersFormat'
import { comboPromotion } from '@/tools/customPromotions'

import rendererEventsService from '@/services/renderer/rendererEvents'

import productsActions from '@/store/products/actions.types'

import customPromotionsViewActions from '@/store/customPromotionsView/actions.types'

import ProductAutoComplete from '@/components/shared/ProductAutoComplete'
import tools from '@/components/CustomPromotionsView/CustomPromotionForm/productSelectorForm.tools'
import MoneyTextField from '@/components/shared/MoneyTextField'

export default {
  name: 'AddComboProducts',
  components: { MoneyTextField, ProductAutoComplete },
  props: {
    value: {
      type: Object,
      default: null,
    },
    validators: {
      type: Object,
      required: true,
    },
    isAnEdition: {
      type: Boolean,
      default: false,
    },
  },
  data() {
    return {
      debounceTimeout: null,
      loading: false,
      productsSelectorKeys: comboPromotion.getProductsKey(),
      selectorFocused: null,
    }
  },
  computed: {
    ...mapState('products', ['data']),
    ...mapState('customPromotionsView', ['newProductDialog']),
    ...mapGetters('customPromotions', [
      'getCustomPromotionsByProductAndTypeWithFilters',
    ]),
    moneyInputsConfig() {
      return moneyTextFieldCountryConfig() || { precision: 2 }
    },
    promotionsByProduct() {
      return this.getCustomPromotionsByProductAndTypeWithFilters(
        promotions.SALE_ITEM_COMBO
      )
    },
    products() {
      const productFromMlp = tools.getProductsFormMLP.call(this)
      const listFirstProduct = tools.getProductsFromInventory.call(
        this,
        this.getCustomFilterProducts(this.productsSelectorKeys[1])
      )
      const listSecondProduct = tools.getProductsFromInventory.call(
        this,
        this.getCustomFilterProducts(this.productsSelectorKeys[0])
      )
      return {
        [this.productsSelectorKeys[0]]: [
          ...listFirstProduct,
          ...productFromMlp,
        ],
        [this.productsSelectorKeys[1]]: [
          ...listSecondProduct,
          ...productFromMlp,
        ],
      }
    },
    someProductAsOpenProduct() {
      return this.productsSelectorKeys.some(
        key =>
          this.value.promotions[key] && this.value.promotions[key].factor > 0
      )
    },
  },
  methods: {
    getTranslatedText,
    ...mapActions('products', [
      productsActions.setMlpFilteredProducts,
      productsActions.addProductFromMLP,
    ]),
    ...mapActions('customPromotionsView', [
      customPromotionsViewActions.toggleAddProductDialog,
      customPromotionsViewActions.updateFilters,
    ]),
    getCustomFilterProducts(key) {
      return product => {
        if (this.value.promotions[key]) {
          return this.value.promotions[key].id !== product.id
        }
        return true
      }
    },
    productInCombo(key, item) {
      const valueKey = this.getOtherKey(key)
      if (!this.value.promotions[valueKey]) return false
      if (!this.promotionsByProduct[this.value.promotions[valueKey].id])
        return false
      return !!comboPromotion.getPromotionBySecondProduct(
        this.promotionsByProduct[this.value.promotions[valueKey].id],
        item.id
      )
    },
    isComboAlreadyPromoted(key, product) {
      if (!product || this.isAnEdition) return
      if (!this.promotionsByProduct[product.id]) return
      const valueKey = this.getOtherKey(key)
      if (!this.value.promotions[valueKey]) return
      const promoFound = comboPromotion.getPromotionBySecondProduct(
        this.promotionsByProduct[product.id],
        this.value.promotions[valueKey].id
      )
      if (!promoFound) return
      this.$root.$emit('toggleCreateForEdit', promoFound)
    },
    getOtherKey(key) {
      return key === this.productsSelectorKeys[0]
        ? this.productsSelectorKeys[1]
        : this.productsSelectorKeys[0]
    },
    selectorWasFocused(key) {
      this.selectorFocused = key
    },
    onBlur(input) {
      this.selectorFocused = null
      this.validators.promotions[input].$touch()
    },
    errorMessages(input) {
      return validate(this.validators.promotions, input, {
        fn: this.getTranslatedText,
      })
    },
    customFilter(item, queryText) {
      return tools.customFilter(item, queryText)
    },
    searchInMlp(search) {
      tools.searchInMlp.call(this, search, this.selectorFocused)
    },
    productWasSelected(key, value) {
      this.isComboAlreadyPromoted(key, value)
      this.setUnitPrice(key, value)
      if (value && this.data.mlp.some(product => product.upc === value.upc)) {
        tools.addNewProductFromMLP.call(this, value.upc)
      }
    },
    async onBarcodeScanned(barcode) {
      if (this.isAnEdition || this.productIsAlreadySelected(barcode)) return
      const inputKeyToUpdate = this.getInputKeyToUpdate()
      if (!inputKeyToUpdate) return
      const productFound = this.selectProduct({ upc: barcode })
      if (productFound) return
      tools.addNewProductFromMLP.call(this, barcode)
    },
    productIsAlreadySelected(upc) {
      return this.productsSelectorKeys.some(
        key =>
          this.value.promotions[key] && this.value.promotions[key].upc === upc
      )
    },
    selectProduct(newProduct) {
      const inputKeyToUpdate = this.getInputKeyToUpdate()
      if (!inputKeyToUpdate) return
      const productFound = this.data.products.find(
        product =>
          product.upc === newProduct.upc && tools.isAvailableProduct(product)
      )
      this.isComboAlreadyPromoted(inputKeyToUpdate, productFound)
      if (productFound) {
        this.value.promotions[inputKeyToUpdate] = productFound
        this.setUnitPrice(inputKeyToUpdate, productFound)
      }
      return productFound
    },
    getInputKeyToUpdate() {
      if (this.selectorFocused) return this.selectorFocused
      let inputKeyToUpdate = this.selectorFocused
      if (!this.value.promotions[this.productsSelectorKeys[1]]) {
        inputKeyToUpdate = this.productsSelectorKeys[1]
      }
      if (!this.value.promotions[this.productsSelectorKeys[0]]) {
        inputKeyToUpdate = this.productsSelectorKeys[0]
      }
      return inputKeyToUpdate
    },
    setUnitPrice(key, product) {
      this.validators.promotions[`${key}UnitPrice`].$reset()
      if (!product || isNaN(Number(product.price))) {
        this.value.promotions[`${key}UnitPrice`] = 0
        return
      }
      this.value.promotions[`${key}UnitPrice`] = formatNumberFromDb(
        Number(product.price)
      )
      this.setTotalWithoutPromo()
    },
    setTotalWithoutPromo() {
      this.value.promotions.totalWithoutPromo = this.productsSelectorKeys.reduce(
        (total, key) => {
          return total + this.value.promotions[`${key}UnitPrice`]
        },
        0
      )
    },
    mlpEventsListener(event, payload) {
      tools.mlpEventsListener.call(this, event, payload)
    },
    addProductEventsListener(event, payload) {
      tools.addProductEventsListener.call(this, event, payload)
    },
  },
  created() {
    this.$barcodeScanner.init(this.onBarcodeScanned)
    this.$root.$on('enable-scanner', () =>
      this.$barcodeScanner.init(this.onBarcodeScanned)
    )
    this.$root.$on('newProductWasAdded', this.selectProduct)
    this.$root.$on('productAddedFromMatch', this.onBarcodeScanned)
    rendererEventsService.subscribe(
      MLP_DB_API_EVENTS.replyChannel,
      this.mlpEventsListener
    )
    rendererEventsService.subscribe(
      ADD_PRODUCT_EVENTS.replyChannel,
      this.addProductEventsListener
    )
  },
  beforeDestroy() {
    this.$root.$off('enable-scanner', () =>
      this.$barcodeScanner.init(this.onBarcodeScanned)
    )
    this.$barcodeScanner.destroy()
    this.$root.$off('newProductWasAdded', this.selectProduct)
    this.$root.$off('productAddedFromMatch', this.onBarcodeScanned)
    rendererEventsService.removeListener(
      MLP_DB_API_EVENTS.replyChannel,
      this.mlpEventsListener
    )
    rendererEventsService.removeListener(
      ADD_PRODUCT_EVENTS.replyChannel,
      this.addProductEventsListener
    )
    this.$root.$emit('enable-scanner-from-form')
  },
}
</script>
