<template>
  <v-container fluid class="promotions-view" id="promotions-view">
    <CustomPromotionsToolbar class="pl-6 pr-5 pt-6" />
    <CustomPromotionsList />
    <DeleteDisabledCustomPromotions />
    <CreateCustomPromotion />
    <EditCustomPromotion />
    <AddNewProductDialog v-if="newProductDialog.isOpen" />
  </v-container>
</template>

<script>
import { mapActions, mapState } from 'vuex'

import customPromotionsViewActions from '@/store/customPromotionsView/actions.types'

import DeleteDisabledCustomPromotions from '@/components/CustomPromotionsView/DeleteDisabledCustomPromotions'
import CustomPromotionsToolbar from '@/components/CustomPromotionsView/CustomPromotionsToolbar'
import CustomPromotionsList from '@/components/CustomPromotionsView/CustomPromotionsList'
import CreateCustomPromotion from '@/components/CustomPromotionsView/CreateCustomPromotion'
import AddNewProductDialog from '@/components/AddNewProductDialog'
import EditCustomPromotion from '@/components/CustomPromotionsView/EditCustomPromotion'

export default {
  name: 'CustomPromotionsView',
  components: {
    EditCustomPromotion,
    AddNewProductDialog,
    CreateCustomPromotion,
    CustomPromotionsList,
    DeleteDisabledCustomPromotions,
    CustomPromotionsToolbar,
  },
  computed: {
    ...mapState('customPromotionsView', ['newProductDialog']),
  },
  methods: {
    ...mapActions('customPromotionsView', [
      customPromotionsViewActions.resetStateValues,
    ]),
  },
  beforeDestroy() {
    this.$root.$emit('sendOpsToSync')
    this[customPromotionsViewActions.resetStateValues]()
  },
}
</script>

<style scoped lang="scss">
.promotions-view {
  height: 100%;
}
</style>
