<template>
  <div>
    <v-btn
      ref="dialogDelete"
      color="error"
      @click="openDialogWantToDelete"
      v-track:click="{
        category: 'CustomPromotions',
        screen: 'DeleteCustomPromotion',
        name: 'Open confirm dialog',
      }"
    >
      <v-icon>mdi-delete-outline</v-icon>
      {{ getTranslatedText('customPromotionsView.delete.button') }}
    </v-btn>
    <DialogCard v-if="deleteCustomPromotionDialog.isOpen" :config="dialog" />
  </div>
</template>

<script>
import { mapActions, mapState } from 'vuex'

import CUSTOM_PROMOTIONS_DB_API_EVENTS from '@/config/events/databaseAPI/customPromotionsEvents'

import { getTranslatedText } from '@/tools/data'

import notificationsService from '@/services/renderer/notifications'
import rendererEventsService from '@/services/renderer/rendererEvents'

import customPromotionsViewActions from '@/store/customPromotionsView/actions.types'
import customPromotionsActions from '@/store/customPromotions/actions.types'

import config from '@/components/CustomPromotionsView/DeleteCustomPromotion/config'
import DialogCard from '@/components/shared/DialogCard'

export default {
  name: 'DeleteCustomPromotion',
  components: { DialogCard },
  props: {
    promotion: {
      type: Object,
      required: true,
    },
  },
  computed: {
    ...mapState('customPromotionsView', ['deleteCustomPromotionDialog']),
    ...mapState('usersView', {
      userId: state => state.selectedUser.id,
    }),
    dialog() {
      return config(
        {
          isOpen: this.deleteCustomPromotionDialog.isOpen,
        },
        {
          closeDialog: this.closeDialog,
          acceptDelete: this.delete,
          track: this.$track,
        }
      )
    },
  },
  methods: {
    ...mapActions('customPromotionsView', [
      customPromotionsViewActions.setDeleteCustomPromotionDialogStatus,
      customPromotionsViewActions.setEditCustomPromotionDialogStatus,
    ]),
    ...mapActions('customPromotions', [
      customPromotionsActions.deleteCustomPromotion,
    ]),
    getTranslatedText,
    openDialogWantToDelete() {
      this[customPromotionsViewActions.setDeleteCustomPromotionDialogStatus](
        true
      )
    },
    delete() {
      this.$track({
        type: 'interaction',
        action: 'click',
        category: 'CustomPromotions',
        screen: 'DeleteCustomPromotion',
        name: 'Confirm deletion',
      })
      this.$loading.show('deleteCustomPromotion')
      rendererEventsService.send(CUSTOM_PROMOTIONS_DB_API_EVENTS.channel, {
        event: CUSTOM_PROMOTIONS_DB_API_EVENTS.events.delete.name,
        data: {
          promotion: this.promotion,
          userId: this.userId,
        },
      })
    },
    closeDialog() {
      this[customPromotionsViewActions.setDeleteCustomPromotionDialogStatus](
        false
      )
    },
    promotionsListener(event, payload) {
      const replies = {
        [CUSTOM_PROMOTIONS_DB_API_EVENTS.events.delete.replies.success]: () => {
          this.$track({
            type: 'system',
            action: 'delete_promotion',
            category: 'CustomPromotions',
            screen: 'DeleteCustomPromotion',
            name: 'Close dialog',
          })
          notificationsService.showSuccess(
            'customPromotionsView.delete.success',
            this.$vuetify.lang
          )
          this[customPromotionsViewActions.setEditCustomPromotionDialogStatus](
            false
          )
          this[customPromotionsActions.deleteCustomPromotion](
            payload.data.promotionId
          )
        },
        [CUSTOM_PROMOTIONS_DB_API_EVENTS.events.delete.replies.error]: () => {
          this.$track({
            type: 'system',
            action: 'error',
            category: 'CustomPromotions',
            screen: 'DeleteCustomPromotion',
            name: 'Error deleting custom promotion',
          })
          notificationsService.showError(
            'customPromotionsView.delete.error',
            this.$vuetify.lang
          )
        },
      }
      if (payload.event in replies) {
        replies[payload.event]()
        this.$loading.hide()
        this.closeDialog()
      }
    },
  },
  beforeMount() {
    rendererEventsService.subscribe(
      CUSTOM_PROMOTIONS_DB_API_EVENTS.replyChannel,
      this.promotionsListener
    )
  },
  beforeDestroy() {
    rendererEventsService.removeListener(
      CUSTOM_PROMOTIONS_DB_API_EVENTS.replyChannel,
      this.promotionsListener
    )
  },
}
</script>
