import { promotions } from '@/config/promotions'

const filtersConfig = (state, methods) => ({
  state,
  methods,
  groupClass: 'pr-4',
  groups: [
    {
      id: 'crate-search-filters',
      controls: [
        {
          id: 'add-promotion-btn',
          type: 'buttonDropdown',
          class: 'pr-4 mt-2',
          label: 'customPromotionsView.toolbar.add.button',
          icon: 'mdi-plus',
          color: 'primary',
          items: getCustomPromotionsToCreate(methods),
        },
        {
          id: 'search-control',
          type: 'input',
          label: 'customPromotionsView.toolbar.search.label',
          placeholder: 'customPromotionsView.toolbar.search.placeholder',
          icon: 'mdi-magnify',
          backgroundColor: 'cardBackgroundSecondary',
          color: 'primary',
          ref: 'promotion-input-search',
          group: 'search',
          onChange: methods.updateSearch,
        },
      ],
    },
    {
      id: 'promotion-type-filters',
      controls: [
        {
          id: 'all-filter-control',
          type: 'button',
          label: 'customPromotionsView.toolbar.filters.all',
          icon: 'mdi-view-module',
          group: 'all',
          color: state.filters.group === 'all' ? 'accent lighten-1' : 'accent',
          onClick: (resetSelector, resetSearchTerm) =>
            methods.filterWasSelected('all', resetSelector, resetSearchTerm),
        },
        {
          id: 'more-for-less-filter-control',
          type: 'button',
          label: 'customPromotionsView.toolbar.filters.moreForLess',
          icon: 'mdi-plus-minus-variant',
          group: 'moreForLess',
          color:
            state.filters.group === 'moreForLess'
              ? 'accent lighten-1'
              : 'accent',
          onClick: (resetSelector, resetSearchTerm) =>
            methods.filterWasSelected(
              'moreForLess',
              resetSelector,
              resetSearchTerm
            ),
        },
        {
          id: 'combo-filter-control',
          type: 'button',
          label: 'customPromotionsView.toolbar.filters.combos',
          icon: 'mdi-food',
          group: 'combo',
          color:
            state.filters.group === 'combo' ? 'accent lighten-1' : 'accent',
          onClick: (resetSelector, resetSearchTerm) =>
            methods.filterWasSelected('combo', resetSelector, resetSearchTerm),
        },
        {
          id: 'active-promotion-control',
          type: 'button',
          label: 'customPromotionsView.toolbar.filters.active',
          icon: 'mdi-timer-check-outline',
          group: 'active',
          color:
            state.filters.group === 'active' ? 'accent lighten-1' : 'accent',
          onClick: (resetSelector, resetSearchTerm) =>
            methods.filterWasSelected('active', resetSelector, resetSearchTerm),
        },
        {
          id: 'disabled-promotion-control',
          type: 'button',
          label: 'customPromotionsView.toolbar.filters.disabled',
          icon: 'mdi-timer-cancel-outline',
          group: 'disabled',
          color:
            state.filters.group === 'disabled' ? 'accent lighten-1' : 'accent',
          onClick: (resetSelector, resetSearchTerm) =>
            methods.filterWasSelected(
              'disabled',
              resetSelector,
              resetSearchTerm
            ),
        },
        {
          id: 'favorite-filter-control',
          type: 'button',
          label: 'customPromotionsView.toolbar.filters.favorite',
          icon: 'mdi-cards-heart',
          group: 'favorite',
          color:
            state.filters.group === 'favorite' ? 'accent lighten-1' : 'accent',

          onClick: (resetSelector, resetSearchTerm) =>
            methods.filterWasSelected(
              'favorite',
              resetSelector,
              resetSearchTerm
            ),
        },
        {
          id: 'clear-filter-control',
          type: 'button',
          label: 'customPromotionsView.toolbar.filters.clear',
          icon: 'mdi-close-circle',
          group: 'favorite',
          color: 'accent',
          onClick: methods.clearFilters,
        },
      ],
    },
  ],
})

const getCustomPromotionsToCreate = methods => {
  return [
    {
      id: promotions.SALE_ITEM_MORE_FOR_LESS,
      icon: 'mdi-plus-minus-variant',
      title: methods.getTranslatedText(
        'customPromotionsView.toolbar.add.moreForLess'
      ),
      click: methods.addPromotion,
      track: 'more for less',
    },
    {
      id: promotions.SALE_ITEM_COMBO,
      icon: 'mdi-food',
      title: methods.getTranslatedText(
        'customPromotionsView.toolbar.add.combo'
      ),
      click: methods.addPromotion,
      track: 'combo',
    },
  ]
}

export default filtersConfig
