<template>
  <ToolBar :config="operations" />
</template>

<script>
import { mapActions, mapGetters, mapState } from 'vuex'

import customPromotionsViewActions from '@/store/customPromotionsView/actions.types'

import ToolBar from '@/components/shared/ToolBar'
import operationsConfig from '@/components/CustomPromotionsView/CustomPromotionsToolbar/Operations/config'

export default {
  name: 'CustomPromotionsOperations',
  components: { ToolBar },
  computed: {
    ...mapState('customPromotionsView', ['viewMode']),
    ...mapGetters('customPromotions', ['getDisabledCustomPromotions']),
    operations() {
      return operationsConfig(
        {
          viewMode: this.viewMode,
          hasFinishedPromotions: !!this.getDisabledCustomPromotions.length,
        },
        {
          deleteDisabledPromotions: this.deleteDisabledPromotions,
          changeViewMode: this.changeViewMode,
        }
      )
    },
  },
  methods: {
    ...mapActions('customPromotionsView', [
      customPromotionsViewActions.setDeleteDisabledCustomPromotionsDialogStatus,
      customPromotionsViewActions.toggleViewMode,
    ]),
    changeViewMode() {
      this[customPromotionsViewActions.toggleViewMode]()
    },
    deleteDisabledPromotions() {
      this[
        customPromotionsViewActions
          .setDeleteDisabledCustomPromotionsDialogStatus
      ](true)
    },
  },
}
</script>
