import { formatDate } from '@/tools/dates'
import { normalizeString } from '@/tools/data'

import light from '@/themes/light'
import dark from '@/themes/dark'

export const tableConfig = (state, methods) => ({
  state,
  methods: {
    ...methods,
    onClick: methods.editPromotion,
    onDblClick: () => null,
  },
  title: 'customPromotionsView.title',
  titleClass: 'pl-2',
  icon: 'mdi-sale',
  loaderColor: { light: light.productLoader, dark: dark.productLoader },
  page: 1,
  rowsPerPage: 6,
  rowOffsetHeight: 48,
  defaultContent: true,
  customSort: (items, sortBy, sortDesc) => {
    const desc = sortDesc[0] ? -1 : 1
    if (sortBy.length === 0) return items
    return items.sort((item1, item2) => {
      if (['finishDate', 'startDate'].includes(sortBy[0])) {
        return sortByDate(item1, item2, sortBy[0], desc)
      }
      return sortByString(item1, item2, sortBy[0], desc)
    })
  },
  itemsPerRow: {
    withoutDetail: {
      lg: 3,
      xl: 4,
    },
  },
  groups: [
    {
      id: 'all',
      icon: 'mdi-view-module',
      title: 'customPromotionsView.toolbar.filters.all',
    },
    {
      id: 'moreForLess',
      icon: 'mdi-plus-minus-variant',
      title: 'customPromotionsView.toolbar.filters.moreForLess',
    },
    {
      id: 'combo',
      icon: 'mdi-food',
      title: 'customPromotionsView.toolbar.filters.combos',
    },
    {
      id: 'active',
      icon: 'mdi-timer-check-outline',
      title: 'customPromotionsView.toolbar.filters.active',
    },
    {
      id: 'disabled',
      icon: 'mdi-timer-cancel-outline',
      title: 'customPromotionsView.toolbar.filters.disabled',
    },
    {
      id: 'favorite',
      icon: 'mdi-cards-heart',
      title: 'customPromotionsView.toolbar.filters.favorite',
    },
  ],
  headers: [
    {
      text: methods.getTranslatedText(
        'customPromotionsView.list.table.type.name'
      ),
      align: 'start',
      value: 'type',
      width: '7%',
      class: 'hover-row',
    },
    {
      text: methods.getTranslatedText(
        'customPromotionsView.list.table.products'
      ),
      align: 'start',
      value: 'product',
      width: '25%',
      class: 'hover-row',
      format: (item, column) => {
        if (item) {
          return `${item.name} ${item.alternativeName}`
        }
        return `${column.promotions.firstProduct.name} ${column.promotions.firstProduct.alternativeName} + ${column.promotions.secondProduct.name} ${column.promotions.secondProduct.alternativeName}`
      },
    },
    {
      text: methods.getTranslatedText(
        'customPromotionsView.list.table.promotions'
      ),
      align: 'start',
      value: 'promotions',
      width: '35%',
      sortable: false,
      class: 'hover-row',
    },
    {
      text: methods.getTranslatedText('customPromotionsView.list.table.start'),
      align: 'center',
      value: 'startDate',
      width: '14%',
      class: 'hover-row',
      format: startDate =>
        startDate
          ? formatDate(startDate)
          : methods.getTranslatedText(
              'customPromotionsView.list.table.noDates'
            ),
    },
    {
      text: methods.getTranslatedText('customPromotionsView.list.table.end'),
      align: 'center',
      value: 'finishDate',
      width: '14%',
      class: 'hover-row',
      format: (finishDate, item) =>
        finishDate
          ? formatDate(finishDate)
          : item.startDate
          ? methods.getTranslatedText(
              'customPromotionsView.list.table.noDateEnd'
            )
          : methods.getTranslatedText(
              'customPromotionsView.list.table.noDates'
            ),
    },
    {
      text: methods.getTranslatedText('customPromotionsView.list.table.active'),
      align: 'end',
      value: 'active',
      width: '5%',
      sortable: false,
      class: 'hover-row',
    },
  ],
})

const sortByDate = (item1, item2, sortBy, desc) => {
  const date1 = new Date(item1[sortBy] || 0)
  const date2 = new Date(item2[sortBy] || 0)
  return (date1.getTime() - date2.getTime()) * desc
}

const sortByString = (item1, item2, sortBy, desc) => {
  let str1 = item1[sortBy]
  let str2 = item2[sortBy]
  if (sortBy === 'product') {
    str1 = item1[sortBy]
      ? `${item1[sortBy].name} ${item1[sortBy].alternativeName}`
      : `${item1.promotions.firstProduct.name} ${item1.promotions.firstProduct.alternativeName} + ${item1.promotions.secondProduct.name} ${item1.promotions.secondProduct.alternativeName}`
    str2 = item2[sortBy]
      ? `${item2[sortBy].name} ${item2[sortBy].alternativeName}`
      : `${item2.promotions.firstProduct.name} ${item2.promotions.firstProduct.alternativeName} + ${item2.promotions.secondProduct.name} ${item2.promotions.secondProduct.alternativeName}`
  }
  return (
    normalizeString(str1.toString()).localeCompare(
      normalizeString(str2.toString())
    ) * desc
  )
}
