<template>
  <v-card
    class="promotion-card"
    elevation="0"
    :ripple="false"
    @click="editPromotion"
    v-track:click="{
      category: 'CustomPromotions',
      screen: 'CustomPromotionCard',
      name: `Edit ${
        isMoreForLessPromotion ? 'more for less' : 'combo'
      } promotion`,
    }"
  >
    <v-card-title
      class="text-subtitle-1 font-weight-medium pb-2 promotion-card__title"
    >
      <div class="title-text">
        <v-icon class="mr-1" color="primary">{{ icon }}</v-icon>
        {{ title }}
      </div>
      <div class="text-right title-actions">
        <span class="text-caption mr-2 grey--text text--lighten-1">
          {{
            getTranslatedText(
              `customPromotionsView.list.card.${
                isActive ? 'active' : 'finished'
              }`
            )
          }}
        </span>
        <v-tooltip v-if="hasSomeIncorrectPromotion" bottom>
          <template v-slot:activator="{ on }">
            <v-icon v-on="on" color="warning" class="warning-promotion mr-2">
              mdi-alert-circle-outline
            </v-icon>
          </template>
          <span>
            {{
              getTranslatedText(
                'customPromotionsView.list.card.errorInPromotions'
              )
            }}
          </span>
        </v-tooltip>
        <v-switch
          v-else
          v-model="isActive"
          inset
          hide-details
          class="ma-0"
          @click.native.capture.stop="changeActivePromotion"
          @change.native.capture.stop
          @click.prevent.stop
        />
        <v-icon
          :color="isFavorite ? 'error' : 'accent'"
          class="favorite-promotion"
          @click.prevent.stop="toggleFavorite"
        >
          {{ isFavorite ? 'mdi-heart' : 'mdi-heart-outline' }}
        </v-icon>
      </div>
    </v-card-title>
    <v-card-text class="promotion-card__text">
      <MoreForLessInfo v-if="isMoreForLessPromotion" :promotion="data" />
      <ComboInfo v-else :promotion="data" />
      <div v-if="data.startDate" class="text-dates">
        <div>
          <p class="text-caption grey--text text--lighten-1">
            {{ getTranslatedText('customPromotionsView.list.card.start') }}
          </p>
          <p class="text-body-1">{{ formatDate(data.startDate) }}</p>
        </div>
        <div class="font-weight-bold">-</div>
        <div>
          <p class="text-caption grey--text text--lighten-1">
            {{ getTranslatedText('customPromotionsView.list.card.end') }}
          </p>
          <p v-if="data.finishDate" class="text-body-1">
            {{ formatDate(data.finishDate) }}
          </p>
          <p v-else class="text-body-1  grey--text text--lighten-1">
            {{ getTranslatedText('customPromotionsView.list.card.noDateEnd') }}
          </p>
        </div>
      </div>
      <div v-else class="text-no-dates d-flex align-center">
        <p class="text-body-1 grey--text text--lighten-1">
          {{ getTranslatedText('customPromotionsView.list.card.noDates') }}
        </p>
      </div>
    </v-card-text>
  </v-card>
</template>

<script>
import { promotions } from '@/config/promotions'

import { formatDate } from '@/tools/dates'
import { formatNumberFromDbToCurrency } from '@/tools/numbersFormat'
import { getTranslatedText } from '@/tools/data'
import { customPromotionIsActive } from '@/tools/promotions'

import MoreForLessInfo from '@/components/CustomPromotionsView/CustomPromotionsList/PaginatedCards/CustomPromotionCard/MoreForLessInfo'
import ComboInfo from '@/components/CustomPromotionsView/CustomPromotionsList/PaginatedCards/CustomPromotionCard/ComboInfo'

export default {
  name: 'CustomPromotionCard',
  components: { ComboInfo, MoreForLessInfo },
  props: {
    data: {
      type: Object,
      required: true,
    },
  },
  computed: {
    isMoreForLessPromotion() {
      return this.data.type === promotions.SALE_ITEM_MORE_FOR_LESS
    },
    title() {
      if (this.isMoreForLessPromotion) {
        return this.getTranslatedText(
          'customPromotionsView.list.card.title.moreForLess'
        )
      }
      return this.getTranslatedText(
        'customPromotionsView.list.card.title.combo'
      )
    },
    icon() {
      if (this.isMoreForLessPromotion) {
        return 'mdi-plus-minus-variant'
      }
      return 'mdi-food'
    },
    isFavorite() {
      return this.data.favorite === 1
    },
    isActive() {
      return customPromotionIsActive(this.data)
    },
    hasSomeIncorrectPromotion() {
      if (this.data.active === 1 || !!this.data.startDate) return false
      if (this.isMoreForLessPromotion) {
        return this.data.promotions.some(
          promo => promo.promotionUnitPrice >= this.data.product.price
        )
      }
      return (
        this.data.promotions.total >=
        this.data.promotions.firstProduct.price +
          this.data.promotions.secondProduct.price
      )
    },
  },
  methods: {
    formatDate,
    formatNumberFromDbToCurrency,
    getTranslatedText,
    toggleFavorite() {
      this.$track({
        type: 'interaction',
        action: 'click',
        category: 'CustomPromotions',
        screen: 'CustomPromotionCard',
        name: `${
          this.data.favorite === 0 ? 'Mark' : 'Unmark'
        } favorite promotion`,
      })
      this.$root.$emit('togglePromotionFavorite', this.data)
    },
    changeActivePromotion() {
      this.$track({
        type: 'interaction',
        action: 'click',
        category: 'CustomPromotions',
        screen: 'CustomPromotionCard',
        name: `${this.data.active === 0 ? 'Enable' : 'Disable'} promotion`,
      })
      this.$root.$emit('changeActivePromotion', this.data)
    },
    editPromotion() {
      this.$root.$emit('openEditPromotion', this.data)
    },
  },
}
</script>

<style scoped lang="scss">
.promotion-card {
  background-color: var(--v-cardBackgroundSecondary-base);
  border-radius: 10px;
  height: 100%;
  min-height: 196px;
  &:hover {
    cursor: pointer;
  }
  &:focus {
    &:before {
      opacity: 0;
    }
  }
  &__title {
    display: flex;
    justify-content: space-between;
    .title-text {
      color: var(--v-primary-base);
    }
    .title-actions {
      display: flex;
      align-items: center;
      gap: 4px;
    }
  }
  &__text {
    .text-dates {
      display: flex;
      gap: 10px;
      align-items: center;
    }
    p {
      margin-bottom: 0;
    }
    .text-no-dates {
      min-height: 44px;
    }
  }
}
</style>
