const config = (state, methods) => ({
  opened: state.isOpen,
  height: 225,
  maxWidth: 500,
  icon: 'mdi-delete',
  title: 'customPromotionsView.delete.title',
  messages: ['customPromotionsView.delete.message'],
  persistent: true,
  buttonTextColor: {
    cancel: 'white',
    accept: 'white',
  },
  buttonColor: {
    cancel: 'accent',
    accept: 'primary',
  },
  onClickCancel: () => {
    methods.track({
      type: 'interaction',
      action: 'click',
      category: 'CustomPromotions',
      screen: 'DeleteCustomPromotion',
      name: 'Cancel confirm',
    })
    methods.closeDialog()
  },
  onClickAccept: methods.acceptDelete,
})

export default config
