<template>
  <PaginatedTable
    :config="configTable"
    class="mx-4"
    id="paginated-promotions-table"
  >
    <template v-slot:type="{ item }">
      <v-tooltip bottom>
        <template v-slot:activator="{ on, attrs }">
          <v-icon color="grey" v-bind="attrs" v-on="on">
            {{ getPromotionTypeIcon(item) }}
          </v-icon>
        </template>
        <span>
          {{ getPromotionTypeTooltip(item) }}
        </span>
      </v-tooltip>
    </template>
    <template v-slot:active="{ item }">
      <v-tooltip v-if="hasSomeIncorrectPromotion(item)" left>
        <template v-slot:activator="{ on }">
          <v-icon v-on="on" small color="warning" class="warning-promotion">
            mdi-circle
          </v-icon>
        </template>
        <span>
          {{
            getTranslatedText(
              'customPromotionsView.list.card.errorInPromotions'
            )
          }}
        </span>
      </v-tooltip>
      <v-icon
        v-else
        :color="isActive(item) ? 'primary' : 'grey lighten-2'"
        small
      >
        mdi-circle
      </v-icon>
    </template>
    <template v-slot:promotions="{ item }">
      <div v-if="isMoreForLessPromotion(item.type)">
        <div
          v-for="(promo, index) in item.promotions"
          :key="promo.id"
          class="d-inline-block"
        >
          <v-chip
            v-if="index < 2"
            small
            color="primary"
            class="mr-2 text-body-1"
            label
          >
            {{ promo.quantity }} x
            {{ formatNumberFromDbToCurrency(promo.total) }}
          </v-chip>
        </div>
        <v-chip
          v-if="item.promotions && item.promotions.length > 3"
          small
          color="primary"
          class="mr-2 text-body-1"
          label
        >
          ...
        </v-chip>
      </div>
      <v-chip v-else small color="primary" class="mr-2 text-body-1" label>
        {{ formatNumberFromDbToCurrency(item.promotions.total) }}
      </v-chip>
    </template>
  </PaginatedTable>
</template>

<script>
import { mapGetters, mapState } from 'vuex'

import { promotions } from '@/config/promotions'

import { getTranslatedText } from '@/tools/data'
import { formatDate } from '@/tools/dates'
import { formatNumberFromDbToCurrency } from '@/tools/numbersFormat'
import { customPromotionIsActive } from '@/tools/promotions'

import { tableConfig } from '@/components/CustomPromotionsView/CustomPromotionsList/PaginatedTable/config'
import PaginatedTable from '@/components/shared/PaginatedTable'

export default {
  name: 'PaginatedCustomPromotionsTable',
  components: { PaginatedTable },
  computed: {
    ...mapState('app', ['windowSize']),
    ...mapState('customPromotionsView', ['filters']),
    ...mapGetters('customPromotions', ['getFilteredCustomPromotions']),
    moreForLessPromotionId() {
      return promotions.SALE_ITEM_MORE_FOR_LESS
    },
    configTable() {
      return tableConfig(
        {
          items: this.getFilteredCustomPromotions,
          windowHeight: this.windowSize.y,
          filters: this.filters,
        },
        {
          editPromotion: this.editPromotion,
          getTranslatedText: this.getTranslatedText,
        }
      )
    },
  },
  methods: {
    formatNumberFromDbToCurrency,
    formatDate,
    getTranslatedText,
    isMoreForLessPromotion(type) {
      return type === promotions.SALE_ITEM_MORE_FOR_LESS
    },
    getPromotionTypeIcon(promo) {
      if (this.isMoreForLessPromotion(promo.type)) {
        return 'mdi-plus-minus-variant'
      }
      return 'mdi-food'
    },
    getPromotionTypeTooltip(promo) {
      if (this.isMoreForLessPromotion(promo.type)) {
        return this.getTranslatedText(
          'customPromotionsView.list.table.type.moreForLess'
        )
      }
      return this.getTranslatedText(
        'customPromotionsView.list.table.type.combo'
      )
    },
    isActive(promo) {
      return customPromotionIsActive(promo)
    },
    hasSomeIncorrectPromotion(promotion) {
      if (promotion.active === 1 || !!promotion.startDate) return false
      if (this.isMoreForLessPromotion(promotion.type)) {
        return promotion.promotions.some(
          promo => promo.promotionUnitPrice >= promotion.product.price
        )
      }
      return (
        promotion.promotions.total >=
        promotion.promotions.firstProduct.price +
          promotion.promotions.secondProduct.price
      )
    },
    editPromotion(promotion) {
      this.$track({
        type: 'interaction',
        action: 'click',
        category: 'CustomPromotions',
        screen: 'PaginatedTable',
        name: `Edit ${
          this.isMoreForLessPromotion(promotion.type)
            ? 'more for less'
            : 'combo'
        } promotion`,
      })
      this.$root.$emit('openEditPromotion', promotion)
    },
  },
}
</script>

<style scoped lang="scss">
#paginated-promotions-table {
  height: 90%;
  :deep(tbody) {
    tr {
      &:hover {
        cursor: pointer;
      }
    }
  }
}
</style>
