import CustomPromotionsFilters from '@/components/CustomPromotionsView/CustomPromotionsToolbar/Filters'
import CustomPromotionsOperations from '@/components/CustomPromotionsView/CustomPromotionsToolbar/Operations'

const toolbarConfig = () => ({
  left: [
    { id: 'filters', type: 'component', component: CustomPromotionsFilters },
  ],
  right: [
    {
      id: 'operations',
      type: 'component',
      component: CustomPromotionsOperations,
    },
  ],
})

export default toolbarConfig
