import MLP_DB_API_EVENTS from '@/config/events/databaseAPI/mlpEvents'

import ADD_PRODUCT_EVENTS from '@/config/events/addProduct'

import rendererEventsService from '@/services/renderer/rendererEvents'

import productsActions from '@/store/products/actions.types'
import customPromotionsViewActions from '@/store/customPromotionsView/actions.types'

const getProductsFromInventory = function(filter = () => true) {
  return this.data.products.reduce((list, product) => {
    if (isAvailableProduct(product) && product.id > 0 && filter(product)) {
      list.push({ ...product, text: getCompletedName(product) })
    }
    return list
  }, [])
}

const isAvailableProduct = product => {
  return (
    product.isGramaje === 0 && product.isGeneric === 0 && product.airTime === 0
  )
}

const getProductsFormMLP = function() {
  return this.data.mlp.reduce((list, product) => {
    if (product.isGramaje === 0) {
      list.push({ ...product, text: getCompletedName(product) })
    }
    return list
  }, [])
}

const getCompletedName = product => {
  return `${product.name} ${product.alternativeName}`
}

const customFilter = (item, queryText) => {
  return (
    item.name.toLowerCase().indexOf(queryText.toLowerCase()) > -1 ||
    item.upc.toLowerCase().indexOf(queryText.toLowerCase()) > -1
  )
}

const searchInMlp = function(search, input = 'product') {
  if (this.debounceTimeout) {
    clearTimeout(this.debounceTimeout)
  }
  if (
    !search ||
    !search.trim() ||
    (!!this.value[input] && this.value[input].name === search)
  ) {
    this.loading = false
    this[productsActions.setMlpFilteredProducts]([])
    return
  }
  this.debounceTimeout = setTimeout(() => {
    this.loading = true
    rendererEventsService.send(MLP_DB_API_EVENTS.channel, {
      event: MLP_DB_API_EVENTS.events.findByPropertiesLikes.name,
      data: [
        { key: 'upc_code', value: search },
        { key: 'prod_name', value: search },
      ],
    })
  }, 500)
}

const mlpEventsListener = function(event, payload) {
  const events = MLP_DB_API_EVENTS.events
  const replies = {
    [events.findByPropertiesLikes.replies.success]: async () => {
      await this[productsActions.setMlpFilteredProducts](payload.data)
      this.loading = false
    },
  }
  if (payload.event in replies) replies[payload.event]()
}

const addNewProductFromMLP = function(barcode) {
  this[customPromotionsViewActions.updateFilters]({ searchTerm: barcode })
  rendererEventsService.send(ADD_PRODUCT_EVENTS.channel, {
    event: ADD_PRODUCT_EVENTS.events.addProductFromMLP.name,
    data: { item: { property: 'upc_code', value: barcode, limit: 1 } },
  })
}

const addProductEventsListener = function(event, payload) {
  const events = ADD_PRODUCT_EVENTS.events
  const replies = {
    [events.addProductFromMLP.replies.success]: async () => {
      await this[productsActions.addProductFromMLP]({
        newProduct: payload.data.newProduct,
      })
      this[productsActions.setMlpFilteredProducts]([])
      this[customPromotionsViewActions.updateFilters]({ searchTerm: null })
      this.selectProduct(payload.data.newProduct)
    },
    [events.addProductFromMLP.replies.error]: () => {
      if (payload.data.error.message === 'newProduct') {
        if (!this.newProductDialog.isOpen) {
          this[customPromotionsViewActions.toggleAddProductDialog](false)
        }
      }
    },
  }
  if (payload.event in replies) replies[payload.event]()
}

export default {
  getProductsFromInventory,
  getProductsFormMLP,
  isAvailableProduct,
  customFilter,
  searchInMlp,
  mlpEventsListener,
  addNewProductFromMLP,
  addProductEventsListener,
}
