<template>
  <DialogCard :config="config.dialog" />
</template>

<script>
import { mapActions, mapGetters, mapState } from 'vuex'

import CUSTOM_PROMOTIONS_DB_API_EVENTS from '@/config/events/databaseAPI/customPromotionsEvents'

import notificationsService from '@/services/renderer/notifications'
import rendererEventsService from '@/services/renderer/rendererEvents'

import customPromotionsViewActions from '@/store/customPromotionsView/actions.types'
import customPromotionsActions from '@/store/customPromotions/actions.types'

import DialogCard from '@/components/shared/DialogCard'
import config from '@/components/CustomPromotionsView/DeleteDisabledCustomPromotions/config'

export default {
  name: 'DeleteDisabledCustomPromotions',
  components: { DialogCard },
  computed: {
    ...mapState('customPromotionsView', [
      'deleteDisabledCustomPromotionsDialog',
    ]),
    ...mapGetters('customPromotions', ['getDisabledCustomPromotions']),
    ...mapState('usersView', {
      userId: state => state.selectedUser.id,
    }),
    config() {
      return config(
        { isOpen: this.deleteDisabledCustomPromotionsDialog.isOpen },
        {
          closeDialog: this.closeDialog,
          acceptDeletion: this.acceptDeletion,
          track: this.$track,
        }
      )
    },
  },
  methods: {
    ...mapActions('customPromotionsView', [
      customPromotionsViewActions.setDeleteDisabledCustomPromotionsDialogStatus,
    ]),
    ...mapActions('customPromotions', [
      customPromotionsActions.bulkCustomPromotionsDeletion,
    ]),
    acceptDeletion() {
      this.$track({
        type: 'interaction',
        action: 'click',
        category: 'CustomPromotions',
        screen: 'DeleteDisabledCustomPromotions',
        name: 'Confirm deletion',
      })
      this.$loading.show('deleteCustomPromotion')
      rendererEventsService.send(CUSTOM_PROMOTIONS_DB_API_EVENTS.channel, {
        event: CUSTOM_PROMOTIONS_DB_API_EVENTS.events.bulkDeletion.name,
        data: {
          promotions: this.getDisabledCustomPromotions,
          userId: this.userId,
        },
      })
    },
    closeDialog() {
      this[
        customPromotionsViewActions
          .setDeleteDisabledCustomPromotionsDialogStatus
      ](false)
    },
    promotionsListener(event, payload) {
      const replies = {
        [CUSTOM_PROMOTIONS_DB_API_EVENTS.events.bulkDeletion.replies
          .success]: () => {
          this.$track({
            type: 'system',
            action: 'delete_disabled_promotions',
            category: 'CustomPromotions',
            screen: 'DeleteDisabledCustomPromotions',
            name: 'Close dialog',
          })
          notificationsService.showSuccess(
            'customPromotionsView.deleteDisabled.success',
            this.$vuetify.lang
          )
          this[customPromotionsActions.bulkCustomPromotionsDeletion](
            payload.data.promotionsIdsDeleted
          )
        },
        [CUSTOM_PROMOTIONS_DB_API_EVENTS.events.bulkDeletion.replies
          .error]: () => {
          this.$track({
            type: 'system',
            action: 'error',
            category: 'CustomPromotions',
            screen: 'DeleteDisabledCustomPromotions',
            name: 'Error deleting disabled custom promotions',
          })
          notificationsService.showError(
            'customPromotionsView.deleteDisabled.error',
            this.$vuetify.lang
          )
        },
      }
      if (payload.event in replies) {
        replies[payload.event]()
        this.$loading.hide()
        this.closeDialog()
      }
    },
  },
  beforeMount() {
    rendererEventsService.subscribe(
      CUSTOM_PROMOTIONS_DB_API_EVENTS.replyChannel,
      this.promotionsListener
    )
  },
  beforeDestroy() {
    rendererEventsService.removeListener(
      CUSTOM_PROMOTIONS_DB_API_EVENTS.replyChannel,
      this.promotionsListener
    )
  },
}
</script>
