<template>
  <PaginatedCards :config="paginatedConfig" id="paginated-promotions-cards" />
</template>

<script>
import { mapGetters, mapState } from 'vuex'

import { normalizeString } from '@/tools/data'
import { getDiffBetweenDates } from '@/tools/dates'

import PaginatedCards from '@/components/shared/PaginatedCards'
import { paginatedConfig } from '@/components/CustomPromotionsView/CustomPromotionsList/PaginatedCards/config'

export default {
  name: 'PaginatedCustomPromotionsCards',
  components: { PaginatedCards },
  computed: {
    ...mapState('app', ['windowSize', 'sidebarOpened']),
    ...mapState('customPromotionsView', ['filters']),
    ...mapGetters('customPromotions', ['getFilteredCustomPromotions']),
    paginatedConfig() {
      return paginatedConfig(
        {
          items: this.getFilteredCustomPromotions,
          filters: this.filters,
          sidebarOpened: this.sidebarOpened,
          currentCardComponent: 'PromotionCard',
          windowHeight: this.windowSize.y,
          windowWidth: this.windowSize.x,
        },
        {
          customSort: this.customSort,
        }
      )
    },
  },
  methods: {
    customSort(items, sortBy, sortDesc) {
      const desc = sortDesc[0] === true ? -1 : 1
      const sorts = {
        product: (firstItem, secondItem) => {
          const firstName = normalizeString(
            firstItem.product
              ? firstItem.product.name
              : firstItem.promotions.firstProduct.name
          )
          const secondName = normalizeString(
            secondItem.product
              ? secondItem.product.name
              : secondItem.promotions.firstProduct.name
          )
          return firstName.localeCompare(secondName) * desc
        },
        startDate: (firstItem, secondItem) => {
          if (!!firstItem.startDate && !!secondItem.startDate) {
            const diffDates = getDiffBetweenDates(
              firstItem.startDate,
              secondItem.startDate
            )
            if (diffDates === 0) return sorts.product(firstItem, secondItem)
            return diffDates * desc
          }
          if (!firstItem.startDate && !!secondItem.startDate) return -1 * desc
          if (!secondItem.startDate && !!firstItem.startDate) return 1 * desc
          return sorts.product(firstItem, secondItem)
        },
        finishDate: (firstItem, secondItem) => {
          if (!!firstItem.finishDate && !!secondItem.finishDate) {
            const diffDates = getDiffBetweenDates(
              firstItem.finishDate,
              secondItem.finishDate
            )
            if (diffDates === 0) return sorts.product(firstItem, secondItem)
            return diffDates * desc
          }
          if (!firstItem.finishDate && !!secondItem.finishDate) return -1 * desc
          if (!secondItem.finishDate && !!firstItem.finishDate) return 1 * desc
          return sorts.product(firstItem, secondItem)
        },
      }
      if (sortBy[0] in sorts) {
        return items.sort(sorts[sortBy[0]])
      }
      return items.sort(
        (firstItem, secondItem) => (firstItem.id - secondItem.id) * desc
      )
    },
  },
}
</script>

<style scoped lang="scss">
#paginated-promotions-cards {
  height: 90%;
  :deep(#data-iterator-no-data) {
    .fill-height {
      height: 70%;
    }
  }
}
</style>
